import argparse
import os

import matplotlib.pyplot as plt
import pandas as pd

# ============================================================
# Visualize RankNet score and uncertainty distributions
#
# 1. Read the mean prediction scores and uncertainty generated by
#      4_calculate_uncertainty.py
#
# 2. Plot RankNet score against prediction uncertainty.
#
# 3. Color samples by Mayo score (M0-M3).
#
# Output:
# Results/
#   <result_date>/
#     fold_<fold>/
#       <datatype>_rank_uncertainty_plot.pdf
#
# Example:
#   python scatter_plot.py <result_date>
#   e.g., python scatter_plot.py 20260825_161805_AL_0
# ============================================================

def read_pred(root_dir, datatype):
    datafile = os.path.join(
        root_dir,
        f"{datatype}_mean_score_and_uncertainty.csv",
    )
    data = pd.read_csv(datafile)

    labels = data["label"]
    scores = data["mean_score"]
    uncertainty = data["var_score"]

    return labels, scores, uncertainty


def scatter_plot(root_dir, datatype):
    # data_load
    labels, scores, uncertainty = read_pred(
        root_dir,
        datatype,
    )

    # figure
    fig, ax = plt.subplots(figsize=(6, 5))

    ax.scatter(
        uncertainty[labels == 0],
        scores[labels == 0],
        s=2,
        c="blue",
        alpha=0.5,
        label="Mayo 0",
    )
    ax.scatter(
        uncertainty[labels == 1],
        scores[labels == 1],
        s=2,
        c="orange",
        alpha=0.5,
        label="Mayo 1",
    )
    ax.scatter(
        uncertainty[labels == 2],
        scores[labels == 2],
        s=2,
        c="green",
        alpha=0.5,
        label="Mayo 2",
    )
    ax.scatter(
        uncertainty[labels == 3],
        scores[labels == 3],
        s=2,
        c="red",
        alpha=0.5,
        label="Mayo 3",
    )

    # Keep the original appearance.
    ax.legend(loc=4, fontsize=12)
    ax.axis([-0.2, 3.5, -3, 13])
    ax.set_xlabel("Uncertainty", fontsize=12)
    ax.set_ylabel("Rank score", fontsize=12)
    fig.tight_layout()

    # save_figure
    output_path = os.path.join(
        root_dir,
        f"{datatype}_rank_uncertainty_plot.pdf",
    )
    fig.savefig(output_path, dpi=300)
    plt.close(fig)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "result_date",
        help="Result directory containing prediction summary files.",
    )
    args = parser.parse_args()

    result_date = args.result_date

    fold_list = [1, 2, 3, 4, 5]
    datatype_list = ["train", "valid", "test"]

    for fold in fold_list:
        for datatype in datatype_list:
            result_path = os.path.join(
                "./../Results",
                result_date,
                f"fold_{fold}",
            )

            scatter_plot(
                result_path,
                datatype,
            )
